rawInput.command:
$repo = "C:\Users\magicvr\Documents\Code\goal-governance"
$gov = Join-Path $repo "docs"
$canonRoot = Join-Path $gov "workspaces"
$legacyRoot = $gov

Write-Output "=== CANONICAL WORKSPACE DIRS ==="
if (Test-Path -LiteralPath $canonRoot) {
  Get-ChildItem -LiteralPath $canonRoot -Directory -Force | ForEach-Object {
    $ws = Join-Path $_.FullName "workspace.md"
    $link = ""
    $item = Get-Item -LiteralPath $_.FullName -Force
    if ($item.LinkType) { $link = " LINK=$($item.LinkType) TARGET=$($item.Target)" }
    $has = Test-Path -LiteralPath $ws
    Write-Output ("DIR={0} has_workspace_md={1}{2}" -f $_.Name, $has, $link)
  }
} else { Write-Output "NO canonical workspaces dir" }

Write-Output "=== LEGACY DIRECT workspace-*/workspace.md ==="
Get-ChildItem -LiteralPath $gov -Directory -Force | Where-Object { $_.Name -like "workspace-*" } | ForEach-Object {
  $ws = Join-Path $_.FullName "workspace.md"
  Write-Output ("DIR={0} has_workspace_md={1}" -f $_.Name, (Test-Path -LiteralPath $ws))
}

Write-Output "=== docs/goals exists ==="
Write-Output (Test-Path -LiteralPath (Join-Path $gov "goals"))

function Show-Frontmatter([string]$path) {
  Write-Output "--- FILE $path ---"
  if (-not (Test-Path -LiteralPath $path)) { Write-Output "MISSING"; return }
  $item = Get-Item -LiteralPath $path -Force
  Write-Output ("LinkType={0} FullName={1}" -f ($(if ($item.LinkType) {$item.LinkType} else {"none"})), $item.FullName)
  $resolved = (Resolve-Path -LiteralPath $path).Path
  Write-Output "resolved=$resolved"
  $lines = Get-Content -LiteralPath $path -TotalCount 80
  $in = $false
  $count = 0
  foreach ($line in $lines) {
    if ($line -eq "---") {
      $count++
      Write-Output $line
      if ($count -ge 2) { break }
      $in = $true
      continue
    }
    if ($count -eq 1) { Write-Output $line }
  }
}

$matches = @()
if (Test-Path -LiteralPath $canonRoot) {
  Get-ChildItem -LiteralPath $canonRoot -Directory -Force | Where-Object { $_.Name -match "^workspace-002-.+" } | ForEach-Object { $matches += $_.FullName }
}
Write-Output "=== workspace-002 match count: $($matches.Count) ==="
$matches | ForEach-Object { Write-Output $_ }

if ($matches.Count -eq 1) {
  $wsFile = Join-Path $matches[0] "workspace.md"
  Show-Frontmatter $wsFile
  Write-Output "=== GOAL-020 dirs in matched workspace ==="
  Get-ChildItem -LiteralPath $matches[0] -Directory -Force | Where-Object { $_.Name -match "^GOAL-020-" } | ForEach-Object {
    $meta = Join-Path $_.FullName "00-meta.md"
    Write-Output ("GOALDIR={0} has_meta={1}" -f $_.Name, (Test-Path -LiteralPath $meta))
  }
}

