rawInput.command:
$repo = "C:\Users\magicvr\Documents\Code\goal-governance"
$wsDir = Join-Path $repo "docs\workspaces\workspace-002-methodology-skills-feedback"
$wsFile = Join-Path $wsDir "workspace.md"

function Show-Frontmatter([string]$path) {
  Write-Output "--- FILE $path ---"
  if (-not (Test-Path -LiteralPath $path)) { Write-Output "MISSING"; return }
  $item = Get-Item -LiteralPath $path -Force
  $lt = if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { $item.LinkType } else { "none" }
  Write-Output "LinkType=$lt FullName=$($item.FullName)"
  $resolved = (Resolve-Path -LiteralPath $path).Path
  Write-Output "resolved=$resolved"
  $lines = Get-Content -LiteralPath $path -TotalCount 120
  $count = 0
  foreach ($line in $lines) {
    if ($line -eq "---") {
      $count++
      Write-Output $line
      if ($count -ge 2) { break }
      continue
    }
    if ($count -eq 1) { Write-Output $line }
  }
}

Show-Frontmatter $wsFile
Write-Output "=== GOAL-020 dirs ==="
Get-ChildItem -LiteralPath $wsDir -Directory -Force | Where-Object { $_.Name -like "GOAL-020-*" } | ForEach-Object {
  Write-Output $_.Name
  $meta = Join-Path $_.FullName "00-meta.md"
  Show-Frontmatter $meta
}
Write-Output "=== goal-tree identity lines for 020 and root ==="
$tree = Join-Path $wsDir "goal-tree.md"
Select-String -LiteralPath $tree -Pattern "GOAL-020|GOAL-001|parent" | ForEach-Object { "{0}:{1}" -f $_.LineNumber, $_.Line.Trim() }

