import json, pathlib
base = pathlib.Path(r'docs/workspaces/workspace-002-methodology-skills-feedback/GOAL-020-goal-drift-detection/attachments')

def load(name):
    return json.loads((base/name).read_text(encoding='utf-8'))

chain = load('s4-delivery-chain.json')
print('CHAIN keys', list(chain)[:30] if isinstance(chain, dict) else type(chain))

def walk(obj, path=''):
    if isinstance(obj, dict):
        for k,v in obj.items():
            if k.lower() in {'conclusion','status','sha','commit','tag','name','html_url','head_sha','merge_commit_sha','checks_passed','checkspassed','version','digest','exitcode','exit_code','unchanged','all_match','matched','mismatch_count','asset_count','count'} or 'sha' in k.lower() or 'match' in k.lower() or 'pass' in k.lower() or 'fail' in k.lower():
                if not isinstance(v, (dict, list)):
                    print(f'{path}.{k}={v}')
            if isinstance(v, (dict, list)) and k.lower() in {'pr','pull','merge','tag','release','runs','summary','result','binding','acceptance','container','ci'}:
                walk(v, path+'.'+k)
    elif isinstance(obj, list) and len(obj) < 8:
        for i,v in enumerate(obj[:6]):
            if isinstance(v, dict):
                walk(v, path+f'[{i}]')

# print top-level scalar and one-level
if isinstance(chain, dict):
    for k,v in chain.items():
        t = type(v).__name__
        n = len(v) if isinstance(v,(list,dict)) else v
        print(f'chain.{k}: {t} {n if isinstance(v,(list,dict)) else \"\"}')

meta = load('s4-release-metadata.json')
print('META type', type(meta).__name__, 'keys' if isinstance(meta, dict) else '', list(meta)[:40] if isinstance(meta, dict) else '')
acc = load('s4-formal-file-acceptance.json')
print('ACC keys', list(acc)[:40] if isinstance(acc, dict) else type(acc))
cont = load('s4-container-acceptance.json')
print('CONT keys', list(cont)[:40] if isinstance(cont, dict) else type(cont))
"@

